import 'dotenv/config';
import express from 'express';
import path from 'path';
import fs from 'fs';
import { createServer as createViteServer } from 'vite';

// Secure backend configuration for Marathon Google Apps Script
const MARATHON_SECRET_KEY = process.env.MARATHON_SECRET_KEY || 'ducbm900966559155';
const MARATHON_APPS_SCRIPT_URL =
  process.env.MARATHON_APPS_SCRIPT_URL ||
  'https://script.google.com/macros/s/AKfycbwwY2MgGaURMrB20UHGVvUZ3INSOrkd8jIQok1JpnDTWMzblecdDOdDTn7qtrbtPPzquw/exec';

// Parse TSV (tab-separated values) generated by Google Apps Script doGet()
function parseTSVData(tsvText: string): any[] {
  const lines = tsvText.split(/\r?\n/).filter((l) => l.trim().length > 0);
  if (lines.length < 2) return [];

  const headers = lines[0].split('\t').map((h) => h.trim().toLowerCase());

  const findCol = (keywords: string[], defIdx: number) => {
    for (let i = 0; i < headers.length; i++) {
      if (keywords.some((kw) => headers[i].includes(kw))) return i;
    }
    return defIdx;
  };

  const colBib = findCol(['bib', 'số bib'], 0);
  const colName = findCol(['tên', 'name', 'họ tên', 'athlete', 'vdv'], 1);
  const colGender = findCol(['giới tính', 'gender', 'sex'], 2);
  const colDistance = findCol(['cự ly', 'distance', 'dist'], 3);
  const colOverallRank = findCol(['overall', 'toàn đoàn', 'hạng chung', 'chung'], 4);
  const colGenderRank = findCol(['gender rank', 'giới tính rank', 'hạng giới tính'], 5);
  const colAG = findCol(['ag', 'nhóm tuổi', 'age group', 'lứa tuổi'], 6);
  const colAgeGroupRank = findCol(['age group rank', 'hạng lứa tuổi', 'hạng nhóm tuổi', 'hạng ag'], 7);
  const colGun = findCol(['guntime', 'gun time', 'gun', 'thời gian gun'], 8);
  const colChip = findCol(['chiptime', 'chip time', 'chip', 'net time', 'thời gian chip'], 9);
  const colPhoto = findCol(['ảnh', 'photo', 'image', 'avatar'], -1);
  const colStart = findCol(['start', 'xuất phát', 'bắt đầu'], -1);
  const colCP1 = findCol(['cp1', 'cp 1', 'checkpoint 1'], -1);
  const colCP1Pace = findCol(['cp1.pace', 'cp1 pace', 'pace cp1', 'cp1_pace'], -1);
  const colCP2 = findCol(['cp2', 'cp 2', 'checkpoint 2'], -1);
  const colCP2Pace = findCol(['cp2.pace', 'cp2 pace', 'pace cp2', 'cp2_pace'], -1);
  const colCP3 = findCol(['cp3', 'cp 3', 'checkpoint 3'], -1);
  const colCP3Pace = findCol(['cp3.pace', 'cp3 pace', 'pace cp3', 'cp3_pace'], -1);
  const colAvgPace = findCol(['average pace', 'avg pace', 'pace tb', 'pace'], -1);

  const normalizeDistance = (dist: string, bib: string): string => {
    const d = (dist || '').trim();
    const upper = d.toUpperCase();
    if (upper === 'M' || upper === 'F') {
      const firstDigit = bib.trim().charAt(0);
      if (firstDigit === '9') return 'Full Marathon';
      if (firstDigit === '8') return 'Half Marathon';
      if (firstDigit === '6' || firstDigit === '1') return '10KM';
      if (firstDigit === '5') return '5KM';
      return 'Full Marathon';
    }
    if (upper.includes('HALF') || upper === 'HM' || upper === '21K' || upper === '21KM') return 'Half Marathon';
    if (upper.includes('FULL') || upper === 'FM' || upper === '42K' || upper === '42KM') return 'Full Marathon';
    if (upper === '10K' || upper === '10KM') return '10KM';
    if (upper === '5K' || upper === '5KM') return '5KM';
    return d || 'Half Marathon';
  };

  const runners: any[] = [];
  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split('\t').map((c) => c.trim());
    const bib = cols[colBib] || '';
    const name = cols[colName] || '';
    if (!bib && !name) continue;

    const rawGender = cols[colGender] || 'M';
    const gUpper = rawGender.trim().toUpperCase();
    const gender = gUpper.startsWith('F') || gUpper.includes('NỮ') ? 'F' : 'M';
    const dist = normalizeDistance(cols[colDistance] || 'Half Marathon', bib);

    runners.push({
      bib,
      name,
      gender,
      distance: dist,
      distanceDisplay: `Đã hoàn thành | Has Completed ${dist}`,
      overallRank: cols[colOverallRank] || '-',
      genderRank: cols[colGenderRank] || '-',
      ag: cols[colAG] || '-',
      ageGroupRank: cols[colAgeGroupRank] || '-',
      gunTime: cols[colGun] || '--:--:--',
      chipTime: cols[colChip] || '--:--:--',
      date: '13/09/2026',
      photoUrl: colPhoto !== -1 ? cols[colPhoto] : undefined,
      startTime: colStart !== -1 ? cols[colStart] : undefined,
      cp1: colCP1 !== -1 ? cols[colCP1] : undefined,
      cp1Pace: colCP1Pace !== -1 ? cols[colCP1Pace] : undefined,
      cp2: colCP2 !== -1 ? cols[colCP2] : undefined,
      cp2Pace: colCP2Pace !== -1 ? cols[colCP2Pace] : undefined,
      cp3: colCP3 !== -1 ? cols[colCP3] : undefined,
      cp3Pace: colCP3Pace !== -1 ? cols[colCP3Pace] : undefined,
      avgPace: colAvgPace !== -1 ? cols[colAvgPace] : undefined,
    });
  }

  return runners;
}

async function startServer() {
  const app = express();
  const PORT = 3000;

  // In-memory cache for marathon data to minimize Google Apps Script execution quotas & optimize speed
  let cachedMarathonData: any = null;
  let cacheTimestamp = 0;
  const CACHE_TTL_MS = 60 * 1000; // 1 minute cache

  // Middleware for large payload (e.g. high-res images)
  app.use(express.json({ limit: '50mb' }));
  app.use(express.urlencoded({ extended: true, limit: '50mb' }));

  // API to save background image permanently to public folder
  app.post('/api/upload-background', (req, res) => {
    try {
      const { dataUrl } = req.body;
      if (!dataUrl) {
        return res.status(400).json({ error: 'No dataUrl provided' });
      }
      const base64Data = dataUrl.replace(/^data:image\/\w+;base64,/, '');
      const buffer = Buffer.from(base64Data, 'base64');

      const publicDir = path.join(process.cwd(), 'public');
      if (!fs.existsSync(publicDir)) {
        fs.mkdirSync(publicDir, { recursive: true });
      }
      const targetPath = path.join(publicDir, 'NA26.png');
      fs.writeFileSync(targetPath, buffer);

      // Also copy to dist/ if dist exists
      const distDir = path.join(process.cwd(), 'dist');
      if (fs.existsSync(distDir)) {
        fs.writeFileSync(path.join(distDir, 'NA26.png'), buffer);
      }

      console.log('Successfully saved NA26.png to public/');
      return res.json({ success: true, url: '/NA26.png' });
    } catch (err: any) {
      console.error('Failed to save background image:', err);
      return res.status(500).json({ error: err.message });
    }
  });

  // API to check if custom certificate exists on server
  app.get('/api/background-status', (req, res) => {
    const publicPath = path.join(process.cwd(), 'public', 'NA26.png');
    const exists = fs.existsSync(publicPath);
    res.json({ exists, url: exists ? '/NA26.png' : null });
  });

  // API to check if race logo exists on server
  app.get('/api/logo-status', (req, res) => {
    const publicPath = path.join(process.cwd(), 'public', 'race_logo.png');
    const exists = fs.existsSync(publicPath);
    res.json({ exists, url: exists ? '/race_logo.png' : null });
  });

  // Admin API: get current default placements
  app.get('/api/default-placements', (req, res) => {
    try {
      const jsonPath = path.join(process.cwd(), 'public', 'default-placements.json');
      if (fs.existsSync(jsonPath)) {
        const data = fs.readFileSync(jsonPath, 'utf8');
        return res.json(JSON.parse(data));
      }
    } catch {}
    res.json({ exists: false });
  });

  // Helper: Normalize raw race data from static files or API
  function normalizeRaceObject(raw: any): any {
    if (!raw || typeof raw !== 'object') return null;
    const cleanSlug = (raw.slug || raw.id || '')
      .toLowerCase()
      .trim()
      .replace(/^\/+|\/+$/g, '')
      .replace(/[^a-z0-9_-]/g, '-');

    if (!cleanSlug && !raw.name) return null;

    const raceId = raw.id || cleanSlug;
    const raceCode = raw.code || cleanSlug.toUpperCase().slice(0, 6);
    let finalBgUrl = raw.defaultBgUrl || '/NA26.png';

    // If backgroundDataUrl base64 is embedded inside static json file
    if (raw.backgroundDataUrl && typeof raw.backgroundDataUrl === 'string' && raw.backgroundDataUrl.startsWith('data:image/')) {
      try {
        const publicDir = path.join(process.cwd(), 'public');
        const bgDir = path.join(publicDir, 'backgrounds');
        if (!fs.existsSync(bgDir)) fs.mkdirSync(bgDir, { recursive: true });

        const base64Data = raw.backgroundDataUrl.replace(/^data:image\/\w+;base64,/, '');
        const buffer = Buffer.from(base64Data, 'base64');
        const filename = `${cleanSlug}.png`;
        fs.writeFileSync(path.join(bgDir, filename), buffer);

        const distBgDir = path.join(process.cwd(), 'dist', 'backgrounds');
        if (fs.existsSync(path.join(process.cwd(), 'dist'))) {
          if (!fs.existsSync(distBgDir)) fs.mkdirSync(distBgDir, { recursive: true });
          fs.writeFileSync(path.join(distBgDir, filename), buffer);
        }
        finalBgUrl = `/backgrounds/${filename}`;
      } catch (bgErr) {
        console.warn(`[Static Races] Could not extract backgroundDataUrl for ${cleanSlug}:`, bgErr);
      }
    }

    return {
      id: raceId,
      slug: cleanSlug,
      code: raceCode,
      name: (raw.name || cleanSlug).trim(),
      shortName: (raw.shortName || raw.name || cleanSlug).trim(),
      city: raw.city || '',
      province: raw.province || '',
      locationFull: raw.locationFull || `${raw.city || ''}, ${raw.province || ''}`.replace(/^, |, $/g, ''),
      date: raw.date || '2026',
      officialUrl: raw.officialUrl || `https://vm.vnexpress.net/${cleanSlug}`,
      defaultLogoUrl: raw.defaultLogoUrl || '/race_logo.png',
      defaultBgUrl: finalBgUrl,
      accentColor: raw.accentColor || '#0369a1',
      themeBadgeBg: raw.themeBadgeBg || 'bg-sky-50 text-sky-700 border-sky-200/80',
      themeDotBg: raw.themeDotBg || 'bg-sky-600',
      storageKeyPrefix: raw.storageKeyPrefix || `vm_${cleanSlug.replace(/[^a-z0-9]/g, '')}`,
      appsScriptUrl: (raw.appsScriptUrl || '').trim(),
      photosScriptUrl: (raw.photosScriptUrl || '').trim(),
      description: raw.description || `Tra cứu kết quả & Chứng nhận điện tử ${raw.name || cleanSlug}`,
      placements: raw.placements || undefined,
      createdAt: raw.createdAt || raw.exportedAt || new Date().toISOString(),
    };
  }

  // Load all races with public/races/*.json as the primary file-based authority
  function loadAllRacesWithStaticFiles(): any[] {
    const publicDir = path.join(process.cwd(), 'public');
    const racesDir = path.join(publicDir, 'races');
    const staticRacesDir = path.join(publicDir, 'static-races');
    const racesFile = path.join(publicDir, 'races-data.json');

    const scanFolders = [racesDir, staticRacesDir];
    let fileRaces: any[] = [];

    for (const folder of scanFolders) {
      if (!fs.existsSync(folder)) continue;
      try {
        const files = fs.readdirSync(folder);
        for (const file of files) {
          if (!file.endsWith('.json')) continue;
          const filePath = path.join(folder, file);
          try {
            const raw = JSON.parse(fs.readFileSync(filePath, 'utf8'));
            const items = Array.isArray(raw) ? raw : [raw];
            for (const item of items) {
              const normalized = normalizeRaceObject(item);
              if (normalized && normalized.slug) {
                const existingIdx = fileRaces.findIndex(
                  (r) => r.id === normalized.id || r.slug === normalized.slug
                );
                if (existingIdx >= 0) {
                  fileRaces[existingIdx] = { ...fileRaces[existingIdx], ...normalized };
                } else {
                  fileRaces.push(normalized);
                }
              }
            }
          } catch (parseErr) {
            console.warn(`[Static Races] Warning: failed to parse ${filePath}:`, parseErr);
          }
        }
      } catch (folderErr) {
        console.warn(`[Static Races] Warning: failed to scan ${folder}:`, folderErr);
      }
    }

    let finalList: any[] = [];

    // Nếu thư mục public/races/ có file, danh sách file này chính là nguồn dữ liệu chuẩn
    if (fileRaces.length > 0) {
      finalList = fileRaces;
    } else {
      finalList = [];
    }

    // Đồng bộ lại file races-data.json với danh sách thực tế hiện tại
    try {
      fs.writeFileSync(racesFile, JSON.stringify(finalList, null, 2), 'utf8');
      const distRacesFile = path.join(process.cwd(), 'dist', 'races-data.json');
      if (fs.existsSync(path.join(process.cwd(), 'dist'))) {
        fs.writeFileSync(distRacesFile, JSON.stringify(finalList, null, 2), 'utf8');
      }
    } catch {}

    return finalList;
  }

  // Races API: Get list of all races (reads both races-data.json and public/races/*.json)
  app.get('/api/races', (req, res) => {
    try {
      const races = loadAllRacesWithStaticFiles();
      return res.json(races);
    } catch (err: any) {
      console.warn('Error loading races:', err);
      return res.status(500).json({ error: err.message || 'Lỗi khi tải danh sách giải' });
    }
  });

  // Export static race API endpoint
  app.get('/api/races/export/:slug', (req, res) => {
    try {
      const slug = req.params.slug;
      const races = loadAllRacesWithStaticFiles();
      const race = races.find((r) => r.slug === slug || r.id === slug);
      if (!race) {
        return res.status(404).json({ error: `Không tìm thấy giải với slug "${slug}"` });
      }

      res.setHeader('Content-Type', 'application/json');
      res.setHeader('Content-Disposition', `attachment; filename="race_api_${race.slug}.json"`);
      return res.json({
        $schema: 'https://marathon-api/v1/race-definition.json',
        ...race,
        exportedAt: new Date().toISOString(),
        instructions: 'Ném file .json này vào thư mục "public/races/" trong mã nguồn. Hệ thống sẽ tự động đọc và tạo giải mới.',
      });
    } catch (err: any) {
      return res.status(500).json({ error: err.message });
    }
  });

  // Admin API: Import static race JSON directly
  app.post('/api/admin/import-static-race', (req, res) => {
    try {
      const { password, raceData } = req.body;
      const ADMIN_PASSWORD = '0966559155';
      if (password !== ADMIN_PASSWORD) {
        return res.status(401).json({ error: 'Mật khẩu quản trị không chính xác.' });
      }

      const normalized = normalizeRaceObject(raceData);
      if (!normalized || !normalized.slug) {
        return res.status(400).json({ error: 'Dữ liệu file JSON không hợp lệ (cần có tên giải và URL slug).' });
      }

      const publicDir = path.join(process.cwd(), 'public');
      const racesFolder = path.join(publicDir, 'races');
      if (!fs.existsSync(racesFolder)) fs.mkdirSync(racesFolder, { recursive: true });

      // Save to public/races/${slug}.json
      fs.writeFileSync(
        path.join(racesFolder, `${normalized.slug}.json`),
        JSON.stringify(normalized, null, 2),
        'utf8'
      );

      // Reload and sync
      const updatedList = loadAllRacesWithStaticFiles();
      return res.json({
        success: true,
        message: `Đã nạp thành công giải "${normalized.name}" từ file API tĩnh!`,
        race: normalized,
        totalRaces: updatedList.length,
      });
    } catch (err: any) {
      return res.status(500).json({ error: err.message });
    }
  });

  // Admin API: Create or update a race
  app.post('/api/admin/races', (req, res) => {
    try {
      const { password, race, backgroundDataUrl } = req.body;
      const ADMIN_PASSWORD = '0966559155';

      if (password !== ADMIN_PASSWORD) {
        return res.status(401).json({ error: 'Mật khẩu quản trị không chính xác (yêu cầu: 0966559155).' });
      }

      if (!race || !race.name || !race.slug) {
        return res.status(400).json({ error: 'Tên giải và URL vào trang (slug) không được để trống.' });
      }

      const cleanSlug = race.slug
        .toLowerCase()
        .trim()
        .replace(/^\/+|\/+$/g, '')
        .replace(/[^a-z0-9_-]/g, '-');

      const publicDir = path.join(process.cwd(), 'public');
      if (!fs.existsSync(publicDir)) fs.mkdirSync(publicDir, { recursive: true });

      let finalBgUrl = race.defaultBgUrl || '/NA26.png';

      // If user uploaded a new background image as base64 dataUrl
      if (backgroundDataUrl && backgroundDataUrl.startsWith('data:image/')) {
        const bgDir = path.join(publicDir, 'backgrounds');
        if (!fs.existsSync(bgDir)) fs.mkdirSync(bgDir, { recursive: true });

        const base64Data = backgroundDataUrl.replace(/^data:image\/\w+;base64,/, '');
        const buffer = Buffer.from(base64Data, 'base64');
        const filename = `${cleanSlug}.png`;
        const filePath = path.join(bgDir, filename);
        fs.writeFileSync(filePath, buffer);

        // Also copy to dist if dist exists
        const distBgDir = path.join(process.cwd(), 'dist', 'backgrounds');
        if (fs.existsSync(path.join(process.cwd(), 'dist'))) {
          if (!fs.existsSync(distBgDir)) fs.mkdirSync(distBgDir, { recursive: true });
          fs.writeFileSync(path.join(distBgDir, filename), buffer);
        }

        finalBgUrl = `/backgrounds/${filename}`;
      }

      // Read existing races
      const racesFile = path.join(publicDir, 'races-data.json');
      let racesList: any[] = [];
      if (fs.existsSync(racesFile)) {
        try {
          racesList = JSON.parse(fs.readFileSync(racesFile, 'utf8'));
        } catch {
          racesList = [];
        }
      }

      const raceId = race.id || cleanSlug;
      const raceCode = race.code || cleanSlug.toUpperCase().slice(0, 6);

      const newRaceObj = {
        id: raceId,
        slug: cleanSlug,
        code: raceCode,
        name: race.name.trim(),
        shortName: race.shortName || race.name.trim(),
        city: race.city || '',
        province: race.province || '',
        locationFull: race.locationFull || `${race.city || ''}, ${race.province || ''}`.replace(/^, |, $/g, ''),
        date: race.date || '2026',
        officialUrl: race.officialUrl || `https://vm.vnexpress.net/${cleanSlug}`,
        defaultLogoUrl: race.defaultLogoUrl || '/race_logo.png',
        defaultBgUrl: finalBgUrl,
        accentColor: race.accentColor || '#0369a1',
        themeBadgeBg: race.themeBadgeBg || 'bg-sky-50 text-sky-700 border-sky-200/80',
        themeDotBg: race.themeDotBg || 'bg-sky-600',
        storageKeyPrefix: `vm_${cleanSlug.replace(/[^a-z0-9]/g, '')}`,
        appsScriptUrl: (race.appsScriptUrl || '').trim(),
        photosScriptUrl: (race.photosScriptUrl || '').trim(),
        description: race.description || `Tra cứu kết quả & Chứng nhận điện tử ${race.name}`,
        placements: race.placements || undefined,
        createdAt: new Date().toISOString(),
      };

      // Update existing or append new
      const existingIdx = racesList.findIndex((r) => r.id === raceId || r.slug === cleanSlug);
      if (existingIdx >= 0) {
        racesList[existingIdx] = { ...racesList[existingIdx], ...newRaceObj };
      } else {
        racesList.push(newRaceObj);
      }

      fs.writeFileSync(racesFile, JSON.stringify(racesList, null, 2), 'utf8');

      // Tự động lưu file cấu hình tĩnh vào public/races/${cleanSlug}.json để có thể copy/tái sử dụng
      const racesFolder = path.join(publicDir, 'races');
      if (!fs.existsSync(racesFolder)) fs.mkdirSync(racesFolder, { recursive: true });
      fs.writeFileSync(
        path.join(racesFolder, `${cleanSlug}.json`),
        JSON.stringify(newRaceObj, null, 2),
        'utf8'
      );

      // Sync with dist if dist exists
      const distRacesFile = path.join(process.cwd(), 'dist', 'races-data.json');
      if (fs.existsSync(path.join(process.cwd(), 'dist'))) {
        fs.writeFileSync(distRacesFile, JSON.stringify(racesList, null, 2), 'utf8');
      }

      return res.json({
        success: true,
        message: `Đã lưu giải đấu "${newRaceObj.name}" thành công!`,
        race: newRaceObj,
      });
    } catch (err: any) {
      console.error('Error saving race:', err);
      return res.status(500).json({ error: err.message || 'Lỗi khi lưu giải đấu' });
    }
  });

  // Admin API: Delete a race
  app.delete('/api/admin/races/:id', (req, res) => {
    try {
      const password = req.headers['x-admin-password'] || req.query.password;
      const ADMIN_PASSWORD = '0966559155';
      if (password !== ADMIN_PASSWORD) {
        return res.status(401).json({ error: 'Mật khẩu quản trị không chính xác.' });
      }

      const raceId = req.params.id;

      const racesFile = path.join(process.cwd(), 'public', 'races-data.json');
      if (fs.existsSync(racesFile)) {
        let racesList: any[] = JSON.parse(fs.readFileSync(racesFile, 'utf8'));
        racesList = racesList.filter((r) => r.id !== raceId && r.slug !== raceId);
        fs.writeFileSync(racesFile, JSON.stringify(racesList, null, 2), 'utf8');
      }

      // Xoá file tĩnh trong public/races/ nếu có
      const raceStaticFile = path.join(process.cwd(), 'public', 'races', `${raceId}.json`);
      if (fs.existsSync(raceStaticFile)) {
        try { fs.unlinkSync(raceStaticFile); } catch {}
      }

      return res.json({ success: true, message: 'Đã xoá giải đấu thành công!' });
    } catch (err: any) {
      return res.status(500).json({ error: err.message || 'Lỗi khi xoá giải đấu' });
    }
  });

  // Admin API: Save placements directly into hardcoded code (src/data/certificatePlacements.ts) and public JSON
  app.post('/api/admin/save-placements', (req, res) => {
    try {
      const { password, placements } = req.body;
      const ADMIN_PASSWORD = '0966559155';

      if (password !== ADMIN_PASSWORD) {
        return res.status(401).json({ error: 'Mật khẩu quản trị không chính xác (yêu cầu: 0966559155).' });
      }

      if (!placements || typeof placements !== 'object') {
        return res.status(400).json({ error: 'Dữ liệu placements không hợp lệ.' });
      }

      // 1. Save to public/default-placements.json for runtime fallback
      const publicDir = path.join(process.cwd(), 'public');
      if (!fs.existsSync(publicDir)) fs.mkdirSync(publicDir, { recursive: true });
      fs.writeFileSync(
        path.join(publicDir, 'default-placements.json'),
        JSON.stringify(placements, null, 2),
        'utf8'
      );

      const distDir = path.join(process.cwd(), 'dist');
      if (fs.existsSync(distDir)) {
        fs.writeFileSync(
          path.join(distDir, 'default-placements.json'),
          JSON.stringify(placements, null, 2),
          'utf8'
        );
      }

      // 2. Format as clean TypeScript code and write directly into src/data/certificatePlacements.ts
      const tsPath = path.join(process.cwd(), 'src', 'data', 'certificatePlacements.ts');
      if (fs.existsSync(tsPath)) {
        let tsContent = fs.readFileSync(tsPath, 'utf8');
        const fieldOrder = ['name', 'distance', 'bib', 'chipTime', 'finishTime', 'overallRank', 'genderRank', 'ageGroupRank'];
        let formattedObj = 'export const DEFAULT_NGHE_AN_PLACEMENTS: CertificatePlacements = {\n';
        
        for (const key of fieldOrder) {
          const item = placements[key];
          if (!item) continue;
          formattedObj += `  ${key}: {\n`;
          formattedObj += `    id: '${item.id || key}',\n`;
          formattedObj += `    label: '${item.label || key}',\n`;
          formattedObj += `    x: ${Number(item.x).toFixed(2)},\n`;
          formattedObj += `    y: ${Number(item.y).toFixed(2)},\n`;
          formattedObj += `    fontSize: ${Math.round(Number(item.fontSize || 40))},\n`;
          formattedObj += `    color: '${item.color || '#ffffff'}',\n`;
          formattedObj += `    align: '${item.align || 'center'}',\n`;
          formattedObj += `    fontWeight: ${Number(item.fontWeight || 700)},\n`;
          formattedObj += `  },\n`;
        }
        formattedObj += `};`;

        // Replace the existing DEFAULT_NGHE_AN_PLACEMENTS block in certificatePlacements.ts
        const regex = /export const DEFAULT_NGHE_AN_PLACEMENTS: CertificatePlacements = \{[\s\S]*?\n\};/;
        if (regex.test(tsContent)) {
          tsContent = tsContent.replace(regex, formattedObj);
          fs.writeFileSync(tsPath, tsContent, 'utf8');
          console.log('[Admin] Successfully saved placements directly into src/data/certificatePlacements.ts');
        }
      }

      return res.json({
        success: true,
        message: 'Đã lưu cấu hình vị trí & kích thước vào code cứng (src/data/certificatePlacements.ts) thành công!',
      });
    } catch (err: any) {
      console.error('[Admin] Failed to save placements:', err);
      return res.status(500).json({ error: err.message || 'Lỗi khi lưu cấu hình vào hệ thống' });
    }
  });

  // Secure Proxy API for Marathon Data: completely hides Google Apps Script URL and Secret Key
  app.get('/api/marathon-data', async (req, res) => {
    try {
      const forceRefresh = req.query.force === 'true' || req.query.refresh === 'true';
      const now = Date.now();

      // Return cached data if still within TTL and not forcing a refresh
      if (!forceRefresh && cachedMarathonData && now - cacheTimestamp < CACHE_TTL_MS) {
        const search = req.query.search ? String(req.query.search).toLowerCase().trim() : '';
        const bib = req.query.bib ? String(req.query.bib).toLowerCase().trim() : '';

        if (bib || search) {
          const list = cachedMarathonData.runners || cachedMarathonData.data || [];
          const filtered = list.filter((r: any) => {
            if (bib) return String(r.bib || '').toLowerCase() === bib;
            if (search) {
              return (
                String(r.bib || '').toLowerCase().includes(search) ||
                String(r.name || '').toLowerCase().includes(search)
              );
            }
            return true;
          });
          return res.json({
            ...cachedMarathonData,
            total: filtered.length,
            data: filtered,
            runners: filtered,
            cached: true,
          });
        }
        return res.json({ ...cachedMarathonData, cached: true });
      }

      // Build target URL appending Secret Key on server side (never exposed to browser)
      const targetUrl = new URL(MARATHON_APPS_SCRIPT_URL);
      targetUrl.searchParams.set('key', MARATHON_SECRET_KEY);
      if (req.query.search) {
        targetUrl.searchParams.set('search', String(req.query.search));
      }
      if (req.query.bib) {
        targetUrl.searchParams.set('bib', String(req.query.bib));
      }

      console.log('[Proxy /api/marathon-data] Fetching data with server secret key...');
      const upstreamRes = await fetch(targetUrl.toString(), {
        redirect: 'follow',
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko)',
          'Accept': 'application/json, text/plain, */*',
        },
      });

      if (!upstreamRes.ok && upstreamRes.status !== 200) {
        return res.status(upstreamRes.status).json({
          error: `Google Apps Script trả về mã lỗi HTTP ${upstreamRes.status}`,
        });
      }

      const rawText = await upstreamRes.text();

      // Check if access was denied by the script's key check
      if (rawText.includes('403 Forbidden') || rawText.includes('Access Denied')) {
        console.error('[Proxy /api/marathon-data] 403 Forbidden received from upstream script');
        return res.status(403).json({
          error: '403 Forbidden: Mã Secret Key không hợp lệ hoặc bị từ chối truy cập.',
        });
      }

      let parsedPayload: any = null;
      const trimmed = rawText.trim();
      if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
        try {
          parsedPayload = JSON.parse(rawText);
        } catch {
          // fallback to TSV parser
        }
      }

      if (parsedPayload) {
        const rawRunners = Array.isArray(parsedPayload)
          ? parsedPayload
          : (parsedPayload.data || parsedPayload.runners || []);

        cachedMarathonData = {
          success: true,
          total: rawRunners.length,
          data: rawRunners,
          runners: rawRunners,
          backgroundUrl: '/NA26.png',
          logoUrl: parsedPayload.logoUrl || '/race_logo.png',
          source: 'appsScript-json',
          cachedAt: new Date().toISOString(),
        };
      } else {
        // Parse TSV text (tab-separated)
        const runners = parseTSVData(rawText);
        cachedMarathonData = {
          success: true,
          total: runners.length,
          data: runners,
          runners: runners,
          backgroundUrl: '/NA26.png',
          logoUrl: '/race_logo.png',
          source: 'appsScript-tsv',
          cachedAt: new Date().toISOString(),
        };
      }

      cacheTimestamp = Date.now();

      // Handle query filters if provided
      const search = req.query.search ? String(req.query.search).toLowerCase().trim() : '';
      const bib = req.query.bib ? String(req.query.bib).toLowerCase().trim() : '';
      if (bib || search) {
        const list = cachedMarathonData.runners || [];
        const filtered = list.filter((r: any) => {
          if (bib) return String(r.bib || '').toLowerCase() === bib;
          if (search) {
            return (
              String(r.bib || '').toLowerCase().includes(search) ||
              String(r.name || '').toLowerCase().includes(search)
            );
          }
          return true;
        });
        return res.json({
          ...cachedMarathonData,
          total: filtered.length,
          data: filtered,
          runners: filtered,
        });
      }

      return res.json(cachedMarathonData);
    } catch (err: any) {
      console.error('[Proxy /api/marathon-data] Error:', err);
      if (cachedMarathonData) {
        return res.json({ ...cachedMarathonData, cached: true, warning: 'Using cache due to network error' });
      }
      return res.status(500).json({ error: err.message || 'Lỗi khi tải dữ liệu từ Google Apps Script' });
    }
  });

  // In-memory cache for Google Apps Script sheet data (reduces load on Google Sheet quota and prevents concurrency errors)
  const sheetDataCache = new Map<string, { data: any; rawText?: string; isJson: boolean; timestamp: number }>();
  const SHEET_CACHE_TTL = 5 * 60 * 1000; // 5 minutes fresh TTL

  // Proxy API for Google Apps Script to bypass browser CORS & cache results
  app.get('/api/proxy-sheet', async (req, res) => {
    const targetUrl = req.query.url as string;
    const forceRefresh = req.query.force === 'true' || req.query.bust === 'true';
    if (!targetUrl) {
      return res.status(400).json({ error: 'Missing url parameter' });
    }

    const cacheKey = targetUrl;
    const cached = sheetDataCache.get(cacheKey);

    // Return fresh cached data if available and not forced
    if (!forceRefresh && cached && Date.now() - cached.timestamp < SHEET_CACHE_TTL) {
      if (cached.isJson) {
        return res.json(cached.data);
      }
      return res.send(cached.rawText);
    }

    // Helper to fetch with timeout and follow redirects
    async function doFetch(attempt = 1): Promise<Response> {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 25000);
      try {
        const resp = await fetch(targetUrl, {
          signal: controller.signal,
          redirect: 'follow',
          headers: {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko)',
            'Accept': 'application/json, text/plain, */*',
          },
        });
        clearTimeout(timeoutId);
        if (!resp.ok && attempt < 2) {
          // Wait 1s and retry once for transient Apps Script busy states
          await new Promise((r) => setTimeout(r, 1000));
          return doFetch(attempt + 1);
        }
        return resp;
      } catch (err) {
        clearTimeout(timeoutId);
        if (attempt < 2) {
          await new Promise((r) => setTimeout(r, 1200));
          return doFetch(attempt + 1);
        }
        throw err;
      }
    }

    try {
      const response = await doFetch(1);
      const contentType = response.headers.get('content-type') || '';
      const text = await response.text();

      let parsedJson: any = null;
      let isJson = false;

      if (contentType.includes('application/json') || text.trim().startsWith('{') || text.trim().startsWith('[')) {
        try {
          parsedJson = JSON.parse(text);
          isJson = true;
        } catch {
          isJson = false;
        }
      }

      if (isJson && parsedJson) {
        // Cache the successful JSON response
        sheetDataCache.set(cacheKey, {
          data: parsedJson,
          isJson: true,
          timestamp: Date.now(),
        });
        return res.json(parsedJson);
      }

      // Cache raw text (e.g. CSV)
      sheetDataCache.set(cacheKey, {
        data: null,
        rawText: text,
        isJson: false,
        timestamp: Date.now(),
      });
      return res.send(text);
    } catch (err: any) {
      console.warn(`[Proxy Sheet] Fetch failed for ${targetUrl}:`, err.message);
      // Fallback: If we have ANY stale cache in memory, serve it to avoid breaking user experience!
      if (cached) {
        console.info(`[Proxy Sheet] Serving stale cache for ${targetUrl} due to upstream fetch failure`);
        if (cached.isJson) {
          return res.json({ ...cached.data, _stale: true });
        }
        return res.send(cached.rawText);
      }
      return res.status(500).json({ error: err.message || 'Không thể kết nối đến nguồn dữ liệu lúc này' });
    }
  });

  // Dedicated Proxy & Ingestion for Runner Photos (BIB + IMG mapping)
  const racePhotosCache = new Map<string, { data: any; timestamp: number }>();
  const PHOTOS_CACHE_TTL = 3 * 60 * 1000; // 3 minutes

  app.get('/api/race-photos', async (req, res) => {
    const targetUrl = req.query.url as string;
    const bib = req.query.bib ? String(req.query.bib).toLowerCase().trim() : '';

    if (!targetUrl) {
      return res.status(400).json({ error: 'Missing url parameter (Google Apps Script URL cho ảnh)' });
    }

    try {
      const cacheKey = `${targetUrl}__${bib}`;
      const cached = racePhotosCache.get(cacheKey);
      if (cached && Date.now() - cached.timestamp < PHOTOS_CACHE_TTL) {
        return res.json({ ...cached.data, cached: true });
      }

      const fetchUrl = new URL(targetUrl);
      if (bib) {
        fetchUrl.searchParams.set('bib', bib);
      }

      const response = await fetch(fetchUrl.toString(), {
        redirect: 'follow',
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko)',
          'Accept': 'application/json, text/plain, */*',
        },
      });

      if (!response.ok) {
        return res.status(response.status).json({
          error: `Google Apps Script ảnh trả về mã lỗi HTTP ${response.status}`,
        });
      }

      const rawText = await response.text();
      let parsed: any = null;
      try {
        parsed = JSON.parse(rawText);
      } catch {
        // Fallback TSV parser if user returned tab-separated text
        const lines = rawText.trim().split(/\r?\n/);
        const list: { bib: string; img: string }[] = [];
        for (let i = 1; i < lines.length; i++) {
          const parts = lines[i].split('\t');
          if (parts.length >= 2) {
            list.push({ bib: parts[0].trim(), img: parts[1].trim() });
          }
        }
        parsed = { success: true, total: list.length, data: list };
      }

      // Convert Google Drive links to direct stream links and flatten comma/newline separated URLs
      const splitAndNormalize = (urls: (string | any)[]): string[] => {
        const out: string[] = [];
        for (const item of urls) {
          if (!item) continue;
          const raw = typeof item === 'string' ? item : (item.img || item.url || '');
          if (!raw) continue;
          const pieces = raw.split(/[\n,;]+/);
          for (const p of pieces) {
            const trimmed = p.trim();
            if (!trimmed) continue;
            const match = trimmed.match(/\/file\/d\/([a-zA-Z0-9_-]+)/) || trimmed.match(/[?&]id=([a-zA-Z0-9_-]+)/);
            if (match && match[1]) {
              out.push(`https://lh3.googleusercontent.com/d/${match[1]}`);
            } else if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
              out.push(trimmed);
            }
          }
        }
        return out;
      };

      if (parsed) {
        if (Array.isArray(parsed.photos)) {
          parsed.photos = splitAndNormalize(parsed.photos);
        }
        if (Array.isArray(parsed.data)) {
          const expandedData: { bib: string; img: string }[] = [];
          for (const item of parsed.data) {
            const itemUrls = splitAndNormalize([item.img || item.url || '']);
            for (const u of itemUrls) {
              expandedData.push({ bib: item.bib, img: u });
            }
          }
          parsed.data = expandedData;
        }
        if (parsed.photosByBib && typeof parsed.photosByBib === 'object') {
          for (const k of Object.keys(parsed.photosByBib)) {
            if (Array.isArray(parsed.photosByBib[k])) {
              parsed.photosByBib[k] = splitAndNormalize(parsed.photosByBib[k]);
            }
          }
        }
      }

      racePhotosCache.set(cacheKey, { data: parsed, timestamp: Date.now() });
      return res.json(parsed);
    } catch (err: any) {
      console.warn('[Proxy /api/race-photos] Error:', err);
      return res.status(500).json({ error: err.message || 'Lỗi khi tải danh sách ảnh thi đấu' });
    }
  });

  // Proxy API to fetch remote background image (e.g. Google Drive, external URL) and bypass CORS
  app.get('/api/proxy-image', async (req, res) => {
    let targetUrl = req.query.url as string;
    if (!targetUrl) {
      return res.status(400).json({ error: 'Missing url parameter' });
    }

    try {
      // If Google Drive link, normalize to direct download/thumbnail link
      if (targetUrl.includes('drive.google.com')) {
        let fileId = '';
        const matchFile = targetUrl.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
        const matchId = targetUrl.match(/[?&]id=([a-zA-Z0-9_-]+)/);
        if (matchFile && matchFile[1]) {
          fileId = matchFile[1];
        } else if (matchId && matchId[1]) {
          fileId = matchId[1];
        }

        if (fileId) {
          // Google user content direct high-res link
          targetUrl = `https://lh3.googleusercontent.com/d/${fileId}`;
        }
      }

      const imgResp = await fetch(targetUrl, {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko)',
        },
      });

      if (!imgResp.ok) {
        // Fallback for google drive uc?export=view
        if (targetUrl.includes('googleusercontent.com/d/')) {
          const fileId = targetUrl.split('/').pop();
          const fallbackUrl = `https://drive.google.com/uc?export=view&id=${fileId}`;
          const fallbackResp = await fetch(fallbackUrl);
          if (fallbackResp.ok) {
            const buffer = Buffer.from(await fallbackResp.arrayBuffer());
            const contentType = fallbackResp.headers.get('content-type') || 'image/png';
            res.setHeader('Content-Type', contentType);
            res.setHeader('Access-Control-Allow-Origin', '*');
            res.setHeader('Cache-Control', 'public, max-age=86400');
            return res.send(buffer);
          }
        }
        return res.status(imgResp.status).send(`Failed to fetch image: HTTP ${imgResp.status}`);
      }

      const contentType = imgResp.headers.get('content-type') || 'image/png';
      const arrayBuffer = await imgResp.arrayBuffer();
      const buffer = Buffer.from(arrayBuffer);

      // Check if response is actually an HTML login/error page instead of an image
      const isHtml = contentType.includes('text/html') || (buffer.length > 0 && buffer[0] === 0x3C && buffer[1] === 0x21); // '<!'
      if (isHtml) {
        return res.status(403).json({ 
          error: 'File Google Drive chưa được bật quyền công khai ("Bất kỳ ai có liên kết"). Vui lòng kiểm tra quyền chia sẻ file.',
          isPermissionError: true
        });
      }

      // Save image to public folder (differentiating logo and certificate background)
      try {
        const publicDir = path.join(process.cwd(), 'public');
        if (!fs.existsSync(publicDir)) fs.mkdirSync(publicDir, { recursive: true });
        
        const isLogo = req.query.type === 'logo' || targetUrl.toLowerCase().includes('logo');
        if (isLogo) {
          fs.writeFileSync(path.join(publicDir, 'race_logo.png'), buffer);
        } else if (req.query.type === 'background') {
          fs.writeFileSync(path.join(publicDir, 'NA26.png'), buffer);
        }
      } catch (saveErr) {
        console.warn('Could not auto-save image to disk:', saveErr);
      }

      res.setHeader('Content-Type', contentType);
      res.setHeader('Access-Control-Allow-Origin', '*');
      res.setHeader('Cache-Control', 'public, max-age=86400');
      return res.send(buffer);
    } catch (err: any) {
      console.error('Error proxying image:', err);
      return res.status(500).json({ error: err.message });
    }
  });

  // Serve static files from public directory
  app.use(express.static(path.join(process.cwd(), 'public')));

  // Vite middleware for development
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  // Cleanup any legacy QN26 files
  try {
    const qnPub = path.join(process.cwd(), 'public', 'QN26_Certificate.png');
    if (fs.existsSync(qnPub)) fs.unlinkSync(qnPub);
    const qnDist = path.join(process.cwd(), 'dist', 'QN26_Certificate.png');
    if (fs.existsSync(qnDist)) fs.unlinkSync(qnDist);
  } catch {}

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server running on port ${PORT}`);
  });
}

startServer();
